class Solution:
    def numSquares(self,n):
        squares=[x*x for x in range(1,isqrt(n)+1)]
        dp=[0]+[n+1]*n
        for total in range(1,n+1):
            dp[total]=1+min(dp[total-s] for s in squares if s<=total)
        return dp[n]

