class Solution:
    def findSubstring(self,s,words):
        width=len(words[0]);need=Counter(words);result=[]
        for offset in range(width):
            left=offset;seen=Counter();count=0
            for right in range(offset,len(s)-width+1,width):
                word=s[right:right+width]
                if word not in need:
                    seen.clear();count=0;left=right+width;continue
                seen[word]+=1;count+=1
                while seen[word]>need[word]:
                    seen[s[left:left+width]]-=1;left+=width;count-=1
                if count==len(words):result.append(left)
        return result

